const id=n=>'45000000-0000-4000-8000-'+String(n).padStart(12,'0');
function digit(value){return String([...value].reduce((sum,c,i)=>sum+(c==='<'?0:/\d/.test(c)?Number(c):c.charCodeAt(0)-55)*[7,3,1][i%3],0)%10);}
function mrz(){const first='P<EGYEXAMPLE<<SYNTHETIC'.padEnd(44,'<'),number='N12345678',birth='900115',expiry='310101',optional='<'.repeat(14),body=number+digit(number)+'EGY'+birth+digit(birth)+'F'+expiry+digit(expiry)+optional+digit(optional);return[first,body+digit(body.slice(0,10)+body.slice(13,20)+body.slice(21,43))];}
function td1(number='Z12345678'){const first='ILARE'+number+digit(number)+'784199000000001',body='900115'+digit('900115')+'F'+'290101'+digit('290101')+'EGY'+'<'.repeat(11);return[first,body+digit(first.slice(5)+body.slice(0,7)+body.slice(8,15)+body.slice(18,29)),'EXAMPLE<<SYNTHETIC'.padEnd(30,'<')];}
const FIELDS={nationalityCode:'EGY',passportNumber:'N12345678',passportType:'ordinary',issuingCountryCode:'EGY',issueDate:'2025-01-01',expiryDate:'2031-01-01',birthDate:'1990-01-15',birthPlace:'Synthetic City',sex:'F',latinFirstName:'Synthetic',latinFamilyName:'Example'};
const extraction=(kind,fields={},extra={})=>({version:1,kind,readable:true,rotation:0,fields:Object.fromEntries(Object.entries(fields).map(([key,value])=>[key,{value,visible:true,confidence:0.999}])),mrzLines:kind==='passport'?mrz():[],portraitBox:null,...extra});
async function fixtures(){return Promise.all([{r:230,g:220,b:210},{r:10,g:150,b:50},{r:20,g:30,b:200},{r:150,g:40,b:10}].map((background,index)=>sharp({create:{width:index===2?600:1200,height:index===2?600:800,channels:3,background}}).png().toBuffer()));}
async function setup(options={}){
 let time=NOW,visionCalls=0,applies=0,stages=0,saves=0,held=false;const pixels=await fixtures(),bytes=new Map(),records={};
 const c={id:'synthetic-case',createdAt:NOW-10000,policyVersion:'synthetic-policy',applicantCount:1,applicants:[{nationality:'مصر',documentType:'passport'}],quote:{total:240},documents:[],paymentStatus:options.unpaid?'unverified':'verified',submissionStatus:'not_submitted'};c.staffVerification={payment:{amount:240,reference:'SYNTHETIC',caseSignature:visaCaseSignature(c)}};
 const store={data:{visaCases:options.noCase?{}:{[CUSTOMER]:c},visaMedia:records},save(){saves++;if(options.failSave)throw Error('private error never persist');}};
 const media={records,epochs:new Map(),get(key,{customer}){const r=records[key];if(!r||r.customer!==customer||r.expiresAt<=time)throw Error('MEDIA_NOT_FOUND');return structuredClone(r);},read(key,opts){return {metadata:this.get(key,opts),bytes:Buffer.from(bytes.get(key))};},storeDerived(customer,{sourceIds,bytes:content,mimeType,kind}){sourceIds.forEach(source=>this.get(source,{customer}));const checksum=sha(content);const prior=Object.values(records).find(r=>r.customer===customer&&r.purpose==='raad_portal_upload'&&r.kind===kind&&r.checksum===checksum&&JSON.stringify(r.sourceIds)===JSON.stringify(sourceIds));if(prior)return this.get(prior.id,{customer});const key=crypto.randomUUID();bytes.set(key,Buffer.from(content));records[key]={id:key,customer,type:'image',mimeType,size:content.length,checksum,purpose:'raad_portal_upload',kind,sourceIds:[...sourceIds],receivedAt:time,expiresAt:time+86400000};store.save();return this.get(key,{customer});}};
 function add(n,index=0,patch={}){const key=id(n),content=patch.mimeType==='application/pdf'?Buffer.from('%PDF-synthetic'):pixels[index];bytes.set(key,Buffer.from(content));records[key]={id:key,customer:CUSTOMER,type:patch.mimeType==='application/pdf'?'document':'image',mimeType:'image/png',size:content.length,checksum:sha(content),receivedAt:NOW-5000+n,expiresAt:NOW+86400000,...patch};return key;}
 const vision={ready:()=>options.ready!==false,async extract({bytes:input,guard}){visionCalls++;guard();if(options.extract)return options.extract({bytes:input,guard,calls:visionCalls});const pixel=await sharp(input).extract({left:0,top:0,width:1,height:1}).raw().toBuffer();guard();if(pixel[0]>200){const fields={...FIELDS};for(const gap of options.gaps||[])delete fields[gap];return extraction('passport',fields,options.crop?{portraitBox:options.crop===true?{x:0.1,y:0.1,width:0.3,height:0.5,confidence:0.999}:options.crop}:{});}if(pixel[1]>100)return extraction('uae_id_front',{latinFullName:'Synthetic Example',birthDate:FIELDS.birthDate,passportNumber:FIELDS.passportNumber,emiratesId:'784199000000001',residenceExpiry:'2029-01-01'});if(pixel[2]>100)return extraction('portrait');return extraction('uae_id_back',{emiratesId:'784199000000001',residenceExpiry:'2029-01-01'});}};
 const env={RAAD_DOCUMENT_OCR_ENABLED:'true',RAAD_APPLICATION_PHONE:'+15550001210',RAAD_CONTACT_EMAIL:'visa@example.test',RAAD_INSURANCE_PHONE:'+15550001211',RAAD_POSTAL_CODE:'00000',...options.env};
 const realRaad=new RaadVisaWorkflow({store,mediaStore:media,now:()=>time,env,canAutomate:()=>true});const raad={get:(...args)=>realRaad.get(...args),applyMachineDossier(...args){applies++;return realRaad.applyMachineDossier(...args);}};
 const fulfilment={blocked:()=>options.blocked||null,data:()=>store.data.visaFulfilment||{jobs:{}},stageDocumentFacts(jobId,{fields,evidenceId}){stages++;const job=this.data().jobs[jobId],result=verifyMachineDossier({store,mediaStore:media,customer:job.customer,applicantIndex:job.applicantIndex,expectedCaseSignature:job.caseSignature,evidenceId,now:()=>time});assert.equal(result.ready,true);assert.deepEqual(result.fields,fields);job.documentEvidence={id:evidenceId};job.state='awaiting_answers';return {ok:true,duplicate:false};}};
 const lock={tryAcquire(){if(held)return false;held=true;return true;},release(){held=false;},onRelease(){return()=>{};},setBusy(value){held=value;}};
 const worker=new VisaDocumentIntake({store,mediaStore:media,vision,raad,fulfilment,env,now:()=>time,lock,report:options.report,mrzVision:options.mrzVision||null,...(options.rasterize?{rasterize:options.rasterize}:{}),...(options.prepare?{prepare:options.prepare}:{})});
 const processAll=async(limit=25)=>{for(let i=0;i<limit;i++){await worker.tick();if(!Object.values(worker.data().jobs).some(j=>['queued','running'].includes(j.status)))break;}};
 return {worker,store,media,records,bytes,c,add,pixels,vision,raad,fulfilment,realRaad,lock,processAll,setTime(value){time=value;},counts:()=>({visionCalls,applies,stages,saves})};
}
async function cachedTd1(f,source,{valid=false,page=1,failed=false}={}){f.worker.enqueue(CUSTOMER,source);const job=Object.values(f.worker.data().jobs).find(job=>job.mediaId===source),lines=td1();if(!valid)lines[2]+='<';const value=extraction('uae_id_back',{emiratesId:'784199000000001'},{mrzLines:lines});value.fields.emiratesId.confidence=0.95;const normalized=await require('../src/raad-attachments').preparePortalImage(f.pixels[3],{mimeType:'image/png',kind:'portrait'});job.pages={[page]:{mediaId:source,page,sha256:sha(normalized.bytes),sourceSha256:f.records[source].checksum,extraction:value}};normalized.bytes.fill(0);job.sourceSha256=f.records[source].checksum;job.status=failed?'failed':'ready';f.td1NeedsMigration=true;return job;}
function td1Worker(f,reader){if(f.td1NeedsMigration){const oldPolicy='2cee114372cc30b247b9f7086a927ffed69a98f831f4d67d09d551ad4f26ca47';f.worker.data().cases[CUSTOMER].policy=oldPolicy;for(const job of Object.values(f.worker.data().jobs))job.policy=oldPolicy;f.td1NeedsMigration=false;}return new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,mrzVision:reader,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock,rasterize:f.worker.rasterize});}
test('all-clear genuine images produce three bounded prepared files, verified machine draft, and no case/payment/staff mutation',async()=>{const f=await setup();const before=structuredClone(f.c);const p=f.add(1,0),r=f.add(2,1),photo=f.add(3,2);for(const key of[p,r,photo])assert.equal(f.worker.enqueue(CUSTOMER,key),true);await f.processAll();const summary=f.worker.summary(CUSTOMER);assert.equal(summary.status,'ready',JSON.stringify(summary));assert.equal(summary.applicants[0].fields.latinGrandfatherName,undefined);assert.equal(f.counts().visionCalls,3);assert.equal(summary.applicants[0].evidence.passportMrzChecked,true);assert.equal(summary.applicants[0].evidence.matchedResidence,true);const state=f.worker.data().cases[CUSTOMER],app=state.applicants[0];assert.equal(app.applied,true);for(const manifest of app.preparedManifest){const file=f.media.read(manifest.mediaId,{customer:CUSTOMER});assert(file.bytes.length<=1000000);assert.equal(sha(file.bytes),manifest.sha256);assert.equal(f.records[manifest.mediaId].kind,manifest.kind);assert(f.records[manifest.mediaId].sourceIds.every(key=>[p,r,photo].includes(key)));}assert.equal(verifyMachineDossier({store:f.store,mediaStore:f.media,customer:CUSTOMER,applicantIndex:0,expectedCaseSignature:visaCaseSignature(f.c),evidenceId:app.id,now:()=>NOW}).ready,true);assert.deepEqual(f.c,before);const revision=f.realRaad.get(CUSTOMER).revision;await f.worker.tick();assert.equal(f.realRaad.get(CUSTOMER).revision,revision);assert.equal(f.counts().visionCalls,3);assert(!JSON.stringify(f.worker.data()).includes('data:image'));});
test('missing routine document labels produce needs_confirmation without invented values or another OCR request',async()=>{const f=await setup({gaps:['passportType','issueDate','birthPlace']});f.add(1,0);f.add(2,1);f.add(3,2);await f.processAll();const result=f.worker.summary(CUSTOMER);assert.equal(result.status,'needs_confirmation',JSON.stringify(result));assert.deepEqual(result.applicants[0].clientFieldsRequired,['passportType','issueDate','birthPlace']);for(const key of result.applicants[0].clientFieldsRequired)assert.equal(Object.hasOwn(result.applicants[0].fields,key),false);assert.equal(f.counts().visionCalls,3);});
test('before payment the dossier stays identity-ready; payment then prepares queued job with metadata only',async()=>{let prepared=0;const f=await setup({unpaid:true,prepare:async(...args)=>{prepared++;return require('../src/raad-attachments').preparePortalImage(...args);}});f.add(1,0);f.add(2,1);f.add(3,2);await f.processAll();assert.equal(f.worker.summary(CUSTOMER).status,'ready');assert.equal(f.worker.summary(CUSTOMER).awaitingPayment,true);assert.equal(f.counts().applies,0);const before=f.counts().visionCalls,transforms=prepared;f.c.paymentStatus='verified';const job={id:id(91),customer:CUSTOMER,caseId:f.c.id,caseSignature:visaCaseSignature(f.c),applicantIndex:0,state:'queued'};f.store.data.visaFulfilment={jobs:{[job.id]:job}};const result=await f.worker.prepareJob(job);assert.equal(result.readyForQuestions,true,JSON.stringify(result));assert.equal(f.counts().stages,1);assert.equal(prepared,transforms);assert.equal(f.counts().visionCalls,before);assert.equal(f.worker.summary(CUSTOMER).awaitingPayment,false);assert.equal(job.state,'awaiting_answers');});
test('a standalone portrait is never replaced by the full passport; a high confidence bounded passport crop is permitted',async()=>{for(const crop of [false,true,{x:0,y:0,width:1,height:1,confidence:0.999},{x:0.1,y:0.1,width:0.1,height:0.1,confidence:0.999}]){const f=await setup({crop});const p=f.add(1,0);f.add(2,1);await f.processAll();const app=f.worker.summary(CUSTOMER).applicants[0];if(crop===true){assert.equal(app.status,'ready');const raw=f.records[app.documents.photo];assert.deepEqual(raw.sourceIds,[p]);const meta=await sharp(f.bytes.get(raw.id)).metadata();assert(meta.width>=300&&meta.height>=300);assert.notEqual(raw.checksum,f.records[app.documents.passport].checksum);}else{assert.equal(app.status,'needs_review');assert.equal(app.documents.photo,null);}}});
test('a 3-page combined PDF is processed sequentially and each page checkpoint is bound to its original source',async()=>{const pix=await fixtures(),seen=[];const f=await setup({crop:true,rasterize:async(bytes,{page,kind})=>{assert.equal(kind,'passport');seen.push(page);if(page>3)throw Object.assign(Error('finite'),{code:'PDF_INVALID'});return [{bytes:Buffer.from(pix[[0,1,3][page-1]]),mimeType:'image/png'}];}});const source=f.add(1,0,{mimeType:'application/pdf'});await f.processAll();assert.equal(f.counts().visionCalls,3);assert.equal(f.worker.summary(CUSTOMER).status,'ready',JSON.stringify(f.worker.summary(CUSTOMER)));const docs=f.worker.data().cases[CUSTOMER].documents;assert.deepEqual(docs.map(d=>d.page),[1,2,3]);assert(docs.every(d=>d.mediaId===source&&d.sourceSha256===f.records[source].checksum));assert.equal(seen.filter(page=>page===4).length,1);for(const role of f.worker.data().cases[CUSTOMER].applicants[0].preparedManifest)assert.deepEqual(f.records[role.mediaId].sourceIds,[source]);});
test('PDF exceeding ten pages is explicitly unsupported and never labelled ready',async()=>{const f=await setup({rasterize:async()=>{throw Object.assign(Error('private pdf path'),{code:'PDF_PAGE_COUNT_UNSUPPORTED'});}});f.add(1,0,{mimeType:'application/pdf'});await f.processAll();assert.equal(f.worker.summary(CUSTOMER).status,'needs_review');assert(f.worker.summary(CUSTOMER).issues.some(i=>i.code==='DOCUMENT_PDF_UNSUPPORTED'));assert.equal(f.counts().visionCalls,0);assert(!JSON.stringify(f.worker.data()).includes('private pdf path'));});
test('duplicate original SHA reuses OCR results without another paid call',async()=>{const f=await setup();f.add(1,0);f.add(2,0);await f.processAll();assert.equal(f.counts().visionCalls,1);assert.equal(Object.keys(f.worker.data().jobs).length,2);});
test('source deletion and erase during provider await cannot resurrect extracted data or create a draft',async()=>{let finish,entered;const enteredPromise=new Promise(resolve=>{entered=resolve;});const f=await setup({extract:async()=>{entered();return new Promise(resolve=>{finish=resolve;});}});const source=f.add(1,0);f.worker.enqueue(CUSTOMER,source);const pending=f.worker.tick();await enteredPromise;delete f.records[source];f.media.epochs.set(CUSTOMER,1);delete f.worker.data().cases[CUSTOMER];for(const [key,job]of Object.entries(f.worker.data().jobs))if(job.customer===CUSTOMER)delete f.worker.data().jobs[key];finish(extraction('passport',FIELDS));await pending;assert.equal(f.worker.data().cases[CUSTOMER],undefined);assert.equal(Object.keys(f.worker.data().jobs).length,0);assert.equal(f.counts().applies,0);});
