test('transport retries are bounded with backoff and do not persist provider errors',async()=>{const f=await setup({extract:async()=>{throw Object.assign(Error('secret provider response'),{code:'DOCUMENT_VISION_NETWORK',retryable:true,retryAfterMs:5000});}});f.add(1,0);await f.worker.tick();assert.equal(f.counts().visionCalls,1);await f.worker.tick();assert.equal(f.counts().visionCalls,1);f.setTime(NOW+5001);await f.worker.tick();assert.equal(f.counts().visionCalls,2);assert.equal(f.worker.summary(CUSTOMER).status,'needs_review');f.setTime(NOW+100000);await f.worker.tick();assert.equal(f.counts().visionCalls,2);assert(!JSON.stringify(f.worker.data()).includes('secret provider response'));});
test('restart preserves completed page checkpoints and does not repeat an interrupted unknown provider outcome',async()=>{const f=await setup();const source=f.add(1,0);f.worker.enqueue(CUSTOMER,source);const job=Object.values(f.worker.data().jobs)[0];job.status='running';job.activePage=1;job.pageAttempts[1]=1;new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock});assert.equal(job.status,'failed');assert.equal(job.issues[0].code,'DOCUMENT_OCR_INTERRUPTED');assert.equal(f.counts().visionCalls,0);});
