test('disabled, missing provider and shared preparation lock never invoke paid OCR',async()=>{for(const options of [{env:{RAAD_DOCUMENT_OCR_ENABLED:'false'}},{ready:false},{}]){const f=await setup(options);const source=f.add(1,0);f.worker.enqueue(CUSTOMER,source);if(!Object.keys(options).length)f.lock.setBusy(true);await f.worker.tick();assert.equal(f.counts().visionCalls,0);}});
