test('restart resumes after a completed PDF page checkpoint without reading that page through vision again',async()=>{const pix=await fixtures(),rasterize=async(bytes,{page})=>{if(page>2)throw Object.assign(Error('finite'),{code:'PDF_INVALID'});return[{bytes:Buffer.from(pix[page-1]),mimeType:'image/png'}];};const f=await setup({crop:true,rasterize}),source=f.add(1,0,{mimeType:'application/pdf'});f.worker.enqueue(CUSTOMER,source);const job=Object.values(f.worker.data().jobs)[0],normalized=await require('../src/raad-attachments').preparePortalImage(pix[0],{mimeType:'image/png',kind:'portrait'});job.sourceSha256=f.records[source].checksum;job.pages[1]={mediaId:source,page:1,sha256:sha(normalized.bytes),sourceSha256:job.sourceSha256,extraction:extraction('passport',FIELDS,{portraitBox:{x:0.1,y:0.1,width:0.3,height:0.5,confidence:0.999}})};job.status='running';job.pageAttempts[1]=1;const resumed=new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock,rasterize});await resumed.tick();assert.equal(f.counts().visionCalls,1);assert.equal(resumed.summary(CUSTOMER).status,'ready',JSON.stringify(resumed.summary(CUSTOMER)));});
test('one independently matched applicant is prepared and staged while another applicant and an ambiguous portrait remain for review',async()=>{const f=await setup({crop:true});f.c.applicantCount=2;f.c.applicants[0].passportNumber=FIELDS.passportNumber;f.c.applicants.push({nationality:'مصر',documentType:'passport',passportNumber:'X000001'});f.c.staffVerification.payment.caseSignature=visaCaseSignature(f.c);f.add(1,0);f.add(2,1);f.add(3,2);await f.processAll();const summary=f.worker.summary(CUSTOMER);assert.equal(summary.status,'needs_review');assert.equal(summary.applicants[0].status,'ready',JSON.stringify(summary));assert.equal(summary.applicants[1].status,'needs_review');assert(summary.issues.some(issue=>issue.code==='DOCUMENT_UNASSIGNED'));assert.equal(f.store.data.raadApplications[CUSTOMER].applicants[1],undefined);const first={id:id(95),customer:CUSTOMER,caseId:f.c.id,caseSignature:visaCaseSignature(f.c),applicantIndex:0,state:'queued'},second={...first,id:id(96),applicantIndex:1};f.store.data.visaFulfilment={jobs:{[first.id]:first,[second.id]:second}};assert.equal((await f.worker.prepareJob(first)).readyForQuestions,true);assert.equal((await f.worker.prepareJob(second)).readyForQuestions,false);assert.equal(first.state,'awaiting_answers');assert.equal(second.state,'queued');assert.equal(f.counts().stages,1);assert.equal(f.worker.summary(CUSTOMER).status,'needs_review');});
