test('policy upgrade retires v1 failed, ready and queued jobs, clears only computed OCR evidence, and reads each source once under v2',async()=>{for(const status of ['failed','ready','queued']){const f=await setup(),source=f.add(1,0);f.worker.enqueue(CUSTOMER,source);const oldJob=Object.values(f.worker.data().jobs)[0],record=f.worker.data().cases[CUSTOMER],oldPolicy='1'.repeat(64),newPolicy='2'.repeat(64);oldJob.policy=oldPolicy;oldJob.status=status;oldJob.pages={1:{mediaId:source,page:1,sha256:'a'.repeat(64),sourceSha256:f.records[source].checksum,extraction:extraction('passport',{...FIELDS,latinFirstName:'OBSOLETE_READ'})}};oldJob.pageAttempts={1:2};oldJob.activePage=1;oldJob.nextAttemptAt=NOW+100000;oldJob.issues=[{code:'DOCUMENT_READ_FAILED',field:'documents',message:'old failure'}];record.policy=oldPolicy;record.status='ready';record.documents=Object.values(oldJob.pages);record.applicants=[{id:id(700),applicantIndex:0,status:'ready',fields:{latinFirstName:'OBSOLETE_READ'}}];record.inputFingerprint='obsolete-input';record.resultFingerprint='obsolete-result';const generation=record.generation,before=structuredClone(f.c);f.store.data.raadApplications={staffDraft:{review:{complete:true},fields:{latinFirstName:'Human'}}};const staff=structuredClone(f.store.data.raadApplications);const make=()=>new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock,policyFingerprint:newPolicy});const upgraded=make();assert.equal(oldJob.status,'stale');assert.deepEqual(oldJob.pages,{});assert.deepEqual(oldJob.pageAttempts,{});assert.equal(oldJob.activePage,undefined);assert.equal(oldJob.nextAttemptAt,undefined);assert.deepEqual(oldJob.issues,[]);assert.equal(upgraded.data().cases[CUSTOMER].generation,generation+1);assert.equal(upgraded.data().cases[CUSTOMER].status,'processing');assert.deepEqual(upgraded.data().cases[CUSTOMER].documents,[]);assert.deepEqual(upgraded.data().cases[CUSTOMER].applicants,[]);await upgraded.tick();assert.equal(f.counts().visionCalls,1);assert(!JSON.stringify(upgraded.data().cases[CUSTOMER]).includes('OBSOLETE_READ'));const fresh=Object.values(upgraded.data().jobs).filter(job=>job.policy===newPolicy);assert.equal(fresh.length,1);assert.equal(fresh[0].status,'ready');assert.equal(fresh[0].generation,generation+1);assert.equal(fresh[0].pageAttempts[1],1);const restarted=make();await restarted.tick();assert.equal(f.counts().visionCalls,1);assert.equal(restarted.data().cases[CUSTOMER].generation,generation+1);assert.deepEqual(f.c,before);assert.deepEqual(f.store.data.raadApplications,staff);}});
test('tick defensively retires a mismatched queued policy even if the case policy was already migrated',async()=>{const f=await setup(),source=f.add(1,0);f.worker.enqueue(CUSTOMER,source);const old=Object.values(f.worker.data().jobs)[0],generation=f.worker.data().cases[CUSTOMER].generation;old.policy='obsolete-policy';old.status='queued';old.pages={1:{extraction:extraction('other')}};await f.worker.tick();assert.equal(old.status,'stale');assert.deepEqual(old.pages,{});assert.equal(f.worker.data().cases[CUSTOMER].generation,generation+1);assert.equal(f.counts().visionCalls,1);assert.equal(Object.values(f.worker.data().jobs).filter(job=>job.status==='ready').length,1);await f.worker.tick();assert.equal(f.counts().visionCalls,1);assert.equal(f.worker.data().cases[CUSTOMER].generation,generation+1);});

test('two anchored passport pages are merged and the verifier binds both real source images',async()=>{
 const base={...FIELDS};delete base.issueDate;delete base.birthPlace;
 const outputs=[extraction('passport',base),extraction('passport',{passportNumber:FIELDS.passportNumber,issueDate:FIELDS.issueDate,birthPlace:FIELDS.birthPlace},{mrzLines:[]}),extraction('uae_id_front',{latinFullName:'Synthetic Example',birthDate:FIELDS.birthDate,passportNumber:FIELDS.passportNumber,emiratesId:'784199000000001',residenceExpiry:'2029-01-01'}),extraction('portrait')];
 const f=await setup({extract:async({bytes})=>{const pixel=await sharp(bytes).extract({left:0,top:0,width:1,height:1}).raw().toBuffer();return pixel[0]>200?outputs[0]:pixel[1]>100?outputs[2]:pixel[2]>100?outputs[3]:outputs[1];}});
 const primary=f.add(1,0),supplement=f.add(2,3);f.add(3,1);f.add(4,2);await f.processAll();
 const state=f.worker.data().cases[CUSTOMER],app=state.applicants[0];assert.equal(state.status,'ready',JSON.stringify(f.worker.summary(CUSTOMER)));
 const raw=f.records[app.documents.passport];assert.deepEqual(raw.sourceIds,[primary,supplement]);
 const m=await sharp(f.bytes.get(raw.id)).metadata();assert(m.height>m.width,'both full landscape source pages should remain stacked');
 assert.equal(app.fields.issueDate,FIELDS.issueDate);assert.equal(app.fields.birthPlace,FIELDS.birthPlace);assert.equal(f.counts().visionCalls,4);
 const verify=()=>verifyMachineDossier({store:f.store,mediaStore:f.media,customer:CUSTOMER,applicantIndex:0,expectedCaseSignature:visaCaseSignature(f.c),evidenceId:app.id,now:()=>NOW});
 assert.equal(verify().ready,true);raw.sourceIds=[primary];assert.equal(verify().ready,false,'dropping the supplementary image must invalidate the prepared file');
});

