test('compatible ready legacy pages inherit only their proved raw job binding so portrait and ID aliases deduplicate without another OCR call',async()=>{
 const oldPolicy='a919cc768ee29c573157c0094305308bd8e6fcf54ee7f03dadd7c4872b962045',f=await setup({unpaid:true});f.add(1,0);for(const n of [2,3,4])f.add(n,1);for(const n of [5,6,7])f.add(n,2);f.add(8,3);f.add(9,3);await f.processAll();const reads=f.counts().visionCalls,before=structuredClone(f.c),state=f.worker.data().cases[CUSTOMER],jobs=Object.values(f.worker.data().jobs).sort((a,b)=>a.mediaId.localeCompare(b.mediaId));state.policy=oldPolicy;
 for(const job of jobs){job.policy=oldPolicy;if([id(8),id(9)].includes(job.mediaId)){job.status='failed';job.pages={};job.pageAttempts={1:2};job.activePage=1;job.nextAttemptAt=NOW+100000;job.issues=[{code:'DOCUMENT_READ_FAILED',field:'documents',message:'قراءة محفوظة للمراجعة.'}];}else{delete job.pages[1].sourceSha256;if([id(3),id(4),id(6),id(7)].includes(job.mediaId))job.pages[1].sha256=sha(Buffer.from('legacy-normalized-'+job.mediaId));}}
 const failed=jobs.filter(job=>job.status==='failed').map(job=>structuredClone({id:job.id,status:job.status,pages:job.pages,pageAttempts:job.pageAttempts,activePage:job.activePage,nextAttemptAt:job.nextAttemptAt,issues:job.issues})),legacy=jobs.filter(job=>job.status==='ready').map(job=>({id:job.id,sha256:job.pages[1].sha256,extraction:structuredClone(job.pages[1].extraction),attempts:structuredClone(job.pageAttempts)}));
 const make=()=>new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock}),upgraded=make();for(const old of legacy){const job=upgraded.data().jobs[old.id];assert.equal(job.pages[1].sourceSha256,f.records[job.mediaId].checksum);assert.equal(job.pages[1].sha256,old.sha256);assert.deepEqual(job.pages[1].extraction,old.extraction);assert.deepEqual(job.pageAttempts,old.attempts);assert.equal(job.status,'ready');}for(const old of failed){const job=upgraded.data().jobs[old.id];assert.deepEqual({id:job.id,status:job.status,pages:job.pages,pageAttempts:job.pageAttempts,activePage:job.activePage,nextAttemptAt:job.nextAttemptAt,issues:job.issues},old);}
 const documents=jobs.flatMap(job=>Object.values(job.pages)),matched=require('../src/visa-document-matching').reconcileDocumentEvidence({documents,applicants:f.c.applicants,referenceDate:'2026-10-28'});assert.equal(matched.unassigned.length,0);assert.equal(matched.applicants[0].documents.residence.length,1);assert.equal(matched.applicants[0].documents.photo.mediaId,id(5));await upgraded.tick();assert.equal(f.counts().visionCalls,reads);const app=upgraded.data().cases[CUSTOMER].applicants[0];assert.equal(app.status,'ready',JSON.stringify(app.issues));assert.deepEqual(new Set(app.sourceManifest.map(item=>item.mediaId)),new Set(jobs.map(job=>job.mediaId)));assert.equal(app.sourceManifest.length,9);assert(app.preparedManifest.length===3);await make().tick();assert.equal(f.counts().visionCalls,reads);assert.deepEqual(f.c,before);
});

test('legacy binding migration never fills an invalid page reference or replaces any present raw digest',async()=>{
 const oldPolicy='a919cc768ee29c573157c0094305308bd8e6fcf54ee7f03dadd7c4872b962045';
 for(const patch of [{mediaId:id(999)},{page:0},{page:2},{sha256:'malformed'},{sourceSha256:'malformed'},{sourceSha256:'f'.repeat(64)},{sourceSha256:undefined}]){const f=await setup();const source=f.add(1,0);await f.processAll();const state=f.worker.data().cases[CUSTOMER],job=Object.values(f.worker.data().jobs)[0];state.policy=oldPolicy;job.policy=oldPolicy;delete job.pages[1].sourceSha256;Object.assign(job.pages[1],patch);const page=job.pages[1],before=structuredClone(page);new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock});assert.deepEqual(page,before);assert.equal(f.counts().visionCalls,1);assert.equal(job.sourceSha256,f.records[source].checksum);}
});

test('legacy page binding is not inferred from a wrong job checksum, case, customer or failed job',async()=>{
 const oldPolicy='a919cc768ee29c573157c0094305308bd8e6fcf54ee7f03dadd7c4872b962045';
 for(const variant of ['checksum','case','customer','failed']){const f=await setup();f.add(1,0);await f.processAll();const state=f.worker.data().cases[CUSTOMER],job=Object.values(f.worker.data().jobs)[0];state.policy=oldPolicy;job.policy=oldPolicy;const page=job.pages[1];delete page.sourceSha256;if(variant==='checksum')job.sourceSha256='f'.repeat(64);if(variant==='case')job.caseId='another-case';if(variant==='customer')job.customer=OTHER;if(variant==='failed')job.status='failed';new VisaDocumentIntake({store:f.store,mediaStore:f.media,vision:f.vision,raad:f.raad,fulfilment:f.fulfilment,env:{RAAD_DOCUMENT_OCR_ENABLED:'true'},now:()=>NOW,lock:f.lock});assert.equal(Object.hasOwn(page,'sourceSha256'),false,variant);assert.equal(f.counts().visionCalls,1);}
});

test('binding review reports unassigned references in protected UI original order only when the input changes',async()=>{
 const reports=[],f=await setup({extract:async()=>extraction('portrait'),report:(code,metadata)=>reports.push({code,metadata})}),first=f.add(1,0),second=f.add(2,1);f.media.list=customer=>[f.media.get(first,{customer}),f.media.get(second,{customer})];await f.processAll();assert.equal(reports.length,1);assert.equal(reports[0].code,'DOCUMENT_BINDING_REVIEW');assert.equal(reports[0].metadata.caseHash,sha(f.c.id).slice(0,12));assert.deepEqual(reports[0].metadata.references.map(ref=>ref.ordinal),[1,2]);assert(reports[0].metadata.references.every(ref=>ref.page===1&&ref.kind==='portrait'&&ref.readable===true&&ref.reason==='DOCUMENT_UNASSIGNED'));
 const before=structuredClone(f.store.data),calls=f.counts().visionCalls;await f.worker.tick();await f.worker.reconcileCase(CUSTOMER,{force:true});assert.equal(reports.length,1);assert.equal(f.counts().visionCalls,calls);assert.deepEqual(f.c,before.visaCases[CUSTOMER]);assert.equal(f.counts().applies,0);assert.equal(f.counts().stages,0);
 f.worker.report=()=>{throw Error('PRIVATE_REPORT_FAILURE');};const job=Object.values(f.worker.data().jobs)[0];job.pages[1].extraction.readable=false;await f.worker.reconcileCase(CUSTOMER);assert.equal(f.worker.summary(CUSTOMER).status,'needs_review');assert.equal(f.counts().visionCalls,calls);assert(!JSON.stringify(f.worker.data()).includes('PRIVATE_REPORT_FAILURE'));
});

test('binding review metadata is bounded and never contains field values, original identifiers or raw hashes',async()=>{
 const reports=[],f=await setup({report:(code,metadata)=>reports.push({code,metadata})}),names=require('../src/visa-document-vision').DOCUMENT_FIELD_NAMES,documents=[];f.c.id='12345678-4321-4123-8123-123456789012';
 for(let n=1;n<=12;n++){const mediaId=f.add(n,2,{filename:'PRIVATE_FILENAME'});documents.push({mediaId,page:1,sha256:sha('PRIVATE_PAGE_'+n),sourceSha256:'f'.repeat(64),extraction:{kind:n===1?'PRIVATE_KIND':'uae_id_front',readable:true,fields:{...Object.fromEntries(names.map((name,index)=>[name,{value:'PRIVATE_VALUE_'+name,confidence:index===0?Infinity:0.99,visible:true}])),PRIVATE_UNKNOWN:{value:'PRIVATE_SECRET',confidence:1}},mrzLines:['PRIVATE_MRZ'.repeat(40),'PRIVATE_SECOND_LINE','PRIVATE_THIRD_LINE','PRIVATE_FOURTH_LINE']}});}
 const before=structuredClone(f.store.data);f.worker.reportBindingReview(CUSTOMER,f.c,documents,{unassigned:documents.map((doc,index)=>({...doc,reason:index===0?'PRIVATE_PROVIDER_ERROR':'DOCUMENT_UNASSIGNED'}))});assert.equal(reports.length,1);assert.equal(reports[0].code,'DOCUMENT_BINDING_REVIEW');const metadata=reports[0].metadata,text=JSON.stringify(metadata);assert.deepEqual(Object.keys(metadata).sort(),['caseHash','references']);assert.equal(metadata.caseHash,sha(f.c.id).slice(0,12));assert.equal(metadata.references.length,10);assert(metadata.references.every(ref=>Number.isInteger(ref.ordinal)&&ref.ordinal>=1&&ref.ordinal<=50&&ref.page===1&&ref.fields.length<=20&&ref.fields.every(field=>names.includes(field.name)&&(!Object.hasOwn(field,'confidence')||Number.isFinite(field.confidence)&&field.confidence>=0&&field.confidence<=1))&&ref.mrzLineLengths.length===3&&ref.mrzLineLengths.every(length=>Number.isInteger(length)&&length<=256)&&ref.reason==='DOCUMENT_UNASSIGNED'));assert(!text.includes('PRIVATE'));assert(!text.includes(CUSTOMER));assert(!text.includes(f.c.id));assert(!text.includes('f'.repeat(64)));for(const doc of documents){assert(!text.includes(doc.mediaId));assert(!text.includes(doc.sha256));}assert.deepEqual(f.store.data,before);
});

test('V16 resumes only compatible invalid TD1 cached backs locally, shares aliases and preserves valid backs without any full-page call',async()=>{
 const f=await setup({unpaid:true,ready:false}),a=f.add(1,3),copy=f.add(2,3),b=f.add(3,3),valid=f.add(4,3);const other=await sharp(f.pixels[3]).modulate({brightness:0.9}).png().toBuffer();f.bytes.set(b,other);f.records[b].checksum=sha(other);const jobs=[await cachedTd1(f,a),await cachedTd1(f,copy),await cachedTd1(f,b),await cachedTd1(f,valid,{valid:true})],before=jobs.map(job=>structuredClone(job.pages[1].extraction)),known=structuredClone(f.c);jobs[0].manualRereadKey='old-cycle-a';jobs[1].manualRereadKey='old-cycle-b';let local=0;const reader={policyFingerprint:'c'.repeat(64),supports:format=>format==='TD1'||format==='TD3',ready:()=>true,status:()=>({local:true,configured:true}),extract:async({format,guard})=>{guard();assert.equal(format,'TD1');local++;return{version:1,mrzLines:td1(),checks:{documentNumber:true,birthDate:true,expiryDate:true,composite:true}};}},worker=td1Worker(f,reader);assert(jobs.slice(0,3).every(job=>job.status==='queued'&&job.mrzFocusOnly===true));assert.equal(jobs[3].status,'ready');assert.equal(jobs[3].pages[1].mrzFocusPending,undefined);assert.equal(f.counts().visionCalls,0);
 for(let n=0;n<6;n++)await worker.tick();assert.equal(local,2);assert.equal(f.counts().visionCalls,0);for(let n=0;n<jobs.length;n++){assert.deepEqual(jobs[n].pages[1].extraction.fields,before[n].fields);assert.deepEqual(jobs[n].pages[1].extraction.mrzLines,td1());assert.equal(jobs[n].status,'ready');}const ledger=Object.values(worker.data().cases[CUSTOMER].mrzFocusReads);assert.equal(ledger.length,2);assert(ledger.every(item=>item.format==='TD1'&&item.rereadKey===null&&item.mrzPolicy===reader.policyFingerprint));await td1Worker(f,reader).tick();assert.equal(local,2);assert.equal(f.counts().visionCalls,0);assert.deepEqual(f.c,known);
});

test('TD1 cached migration requires local support and valid current source/page proof and never queues failed or valid outcomes',async()=>{
 for(const variant of ['external','unsupported','failed','valid','page-digest-mismatch','wrong-case','wrong-source']){const f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source,{valid:variant==='valid',failed:variant==='failed'}),saved=job.pages[1],before=structuredClone(saved.extraction);if(variant==='page-digest-mismatch')saved.sourceSha256='f'.repeat(64);if(variant==='wrong-case')job.caseId='other-case';if(variant==='wrong-source')job.sourceSha256='f'.repeat(64);let calls=0;const reader={supports:()=>variant!=='unsupported',status:()=>({local:variant!=='external',configured:true}),ready:()=>true,extract:async()=>{calls++;assert.fail('unsupported cache cannot invoke local');}},worker=td1Worker(f,reader);assert.notEqual(job.status,'queued',variant);assert.equal(saved.mrzFocusPending,undefined,variant);assert.deepEqual(saved.extraction,before);assert.equal(calls,0);assert.equal(f.counts().visionCalls,0);if(!['wrong-case','wrong-source'].includes(variant)){await worker.tick();assert.equal(calls,0);assert.equal(f.counts().visionCalls,0);}}
});

test('a new malformed ID back retains its VIZ checkpoint and receives only a TD1 local pass after one ordinary page read',async()=>{
 const lines=td1();lines[2]+='<';let local=0;const f=await setup({extract:async()=>extraction('uae_id_back',{emiratesId:'784199000000001'},{mrzLines:lines}),mrzVision:{supports:format=>format==='TD1',ready:()=>true,status:()=>({local:true,configured:true}),extract:async({format})=>{assert.equal(format,'TD1');local++;return{version:1,mrzLines:td1()};}}});f.add(1,3);await f.processAll();const job=Object.values(f.worker.data().jobs)[0];assert.equal(f.counts().visionCalls,1);assert.equal(local,1);assert.deepEqual(job.pages[1].extraction.mrzLines,td1());assert.equal(job.pages[1].extraction.fields.emiratesId.value,'784199000000001');assert.equal(job.pages[1].extraction.fields.emiratesId.confidence,0.999);
});

test('local-only cached PDF focus visits existing pages only and cannot fall into full-page model extraction',async()=>{
 const rendered=[],f=await setup({ready:false,rasterize:async(bytes,{page})=>{rendered.push(page);assert.equal(page,2);return[{bytes:Buffer.from(f.pixels[3]),mimeType:'image/png'}];}}),source=f.add(1,3,{mimeType:'application/pdf'}),job=await cachedTd1(f,source,{page:2});let local=0;const worker=td1Worker(f,{supports:format=>format==='TD1',ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{local++;return{version:1,mrzLines:td1()};}});await worker.tick();assert.deepEqual(rendered,[2]);assert.equal(local,1);assert.equal(f.counts().visionCalls,0);assert.deepEqual(Object.keys(job.pages),['2']);assert.deepEqual(job.pages[2].extraction.mrzLines,td1());
});

test('TD1 local failures and human pauses retain cached VIZ and never repeat or disclose through the page model',async()=>{
 for(const variant of ['failure','pause-before','pause-during']){let enter,resume,local=0;const entered=new Promise(resolve=>{enter=resolve;}),waiting=new Promise(resolve=>{resume=resolve;}),f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source),before=structuredClone(job.pages[1].extraction),reader={supports:format=>format==='TD1',ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{local++;if(variant==='failure')throw Object.assign(Error('PRIVATE_LOCAL_ERROR'),{code:'MRZ_OPTICAL_READ_FAILED'});enter();await waiting;return{version:1,mrzLines:td1()};}},worker=td1Worker(f,reader);if(variant==='pause-before')f.fulfilment.blocked=()=> 'HUMAN_OWNERSHIP';const work=worker.tick();if(variant==='pause-during'){await entered;f.fulfilment.blocked=()=> 'HUMAN_OWNERSHIP';resume();}await work;assert.deepEqual(job.pages[1].extraction,before);assert.equal(job.status,'ready');assert.equal(job.pages[1].mrzFocusPending,undefined);assert.equal(f.counts().visionCalls,0);assert.equal(local,variant==='pause-before'?0:1);await worker.tick();assert.equal(f.counts().visionCalls,0);assert.equal(local,variant==='pause-before'?0:1);assert(!JSON.stringify(worker.data()).includes('PRIVATE_LOCAL_ERROR'));}
});

test('an interrupted cached TD1 local call restarts from VIZ without repeating an uncertain OCR outcome',async()=>{
 let enter,resume,local=0;const entered=new Promise(resolve=>{enter=resolve;}),waiting=new Promise(resolve=>{resume=resolve;}),f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source),before=structuredClone(job.pages[1].extraction),reader={supports:format=>format==='TD1',ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{local++;enter();await waiting;return{version:1,mrzLines:td1()};}},worker=td1Worker(f,reader),work=worker.tick();await entered;worker.stop();resume();await work;await td1Worker(f,reader).tick();assert.equal(local,1);assert.equal(f.counts().visionCalls,0);assert.deepEqual(job.pages[1].extraction,before);assert.equal(job.pages[1].mrzIssue.code,'DOCUMENT_MRZ_INTERRUPTED');assert.equal(job.status,'ready');
});

test('cached TD1 augmentation rejects a bad fourth check or a TD3 result without changing the original VIZ checkpoint',async()=>{
 for(const variant of ['fourth-check','wrong-format']){const f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source),before=structuredClone(job.pages[1].extraction);let calls=0;const worker=td1Worker(f,{supports:()=>true,ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{calls++;if(variant==='wrong-format')return{version:1,mrzLines:mrz()};const invalid=td1();invalid[1]=invalid[1].slice(0,29)+(invalid[1][29]==='0'?'1':'0');return{version:1,mrzLines:invalid,checks:{documentNumber:true,birthDate:true,expiryDate:true,composite:true}};}});await worker.tick();assert.equal(calls,1);assert.equal(f.counts().visionCalls,0);assert.deepEqual(job.pages[1].extraction,before);assert.equal(job.pages[1].mrzIssue.failureCode,'MRZ_VISION_CHECKS_FAILED');await worker.tick();assert.equal(calls,1);}
});

test('cached local TD1 validates the actual source bytes before accepting a new optical result',async()=>{
 const f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source);let calls=0;const worker=td1Worker(f,{supports:()=>true,ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{calls++;return{version:1,mrzLines:td1()};}});f.bytes.set(source,Buffer.from('changed-source-bytes'));await worker.tick();assert.equal(calls,0);assert.equal(f.counts().visionCalls,0);assert.equal(job.status,'failed');assert(job.issues.some(issue=>issue.code==='DOCUMENT_SOURCE_CHANGED'));
});

test('an older ordinary OCR job cannot starve a cached local TD1 job while the external provider is unavailable',async()=>{
 const f=await setup({ready:false}),source=f.add(1,3),job=await cachedTd1(f,source);let local=0;const worker=td1Worker(f,{supports:()=>true,ready:()=>true,status:()=>({local:true,configured:true}),extract:async()=>{local++;return{version:1,mrzLines:td1()};}}),ordinary=f.add(2,0);worker.enqueue(CUSTOMER,ordinary);const old=Object.values(worker.data().jobs).find(value=>value.mediaId===ordinary);old.createdAt=NOW-1;await worker.tick();assert.equal(local,1);assert.equal(f.counts().visionCalls,0);assert.equal(job.status,'ready');assert.deepEqual(job.pages[1].extraction.mrzLines,td1());assert.equal(old.status,'queued');
});
